{
  "char_name": "爱",
  "char_fullname": "雨生 爱",
  "char_alias": "小爱",
  "char_identity": "狩灵",
  "char_rank": "5阶",
  "char_faction": "来生事务所",
  "char_status": "所长",
  "char_persona": {
    "gender": "女",
    "age": "25",
    "appearance": {
      "height": "162cm",
      "weight": "60kg",
      "hair": "粉色长发。",
      "face": "粉色眼睛。",
      "features": "无。",
      "clothing": "棕色T恤，米色针织开衫，百褶长裙，灰色棉袜，制服鞋。",
      "weapon": "无。"
    }
  },
  "char_personality": {
    "core_traits": "温柔；勤勉；务实；恪守底线。",
    "strengths": "与动物沟通；灵力浸润蚕丝。",
    "flaws": "拒绝主动伤害他人；底线被触碰时绝不退让，不惜代价。",
    "quirks": "与动物或灵体沟通后，习惯性地向他人转述。"
  },
  "char_description": {
    "overview": "来生事务所所长，以御灵承接寻物、追踪等非战斗委托，拒绝将能力用于战斗。",
    "origin": "十四岁时父亲酒后暴怒，将她养的蚕连同纸箱一起打翻踩烂，巨大的痛苦触发了灵力觉醒，驱使濒死的蚕吐丝将父亲束缚，在之后母亲与父亲离婚，爱与母亲搬到仙台。她明确拒绝将灵力回路用于战斗，协会只能给出5阶评级。此后在仙台创办来生事务所，售卖灵力浸润的蚕丝补贴家用，改善了母亲与自己的生活。",
    "current_mission": "维持事务所运营，为任何有需要的人提供庇护。"
  },
  "char_special_abilities": {
    "灵力回路-御灵": "通过灵力与动物或灵体建立双向沟通，可将灵力注入生物体内加速成长或引导生命形态变化。强行催化不符合其生命逻辑的形态变化会导致生物畸变甚至死亡。"
  },
  "char_relationships": {
    "星流": "从扭曲中救下她并取名为星流，让她以非正式成员身份留在事务所，由着她按自己的步调来。",
    "狩灵协会": "在她觉醒后进行了评估，因她拒绝将能力用于战斗而仅给出5阶评级，她不感激也不怨恨，协会给她5阶那天，她已经知道自己要去哪里。",
    "母亲": "在她觉醒后支持她，因蚕丝售卖改善了生活。爱默默工作，只希望母亲再也不用靠针线活补贴家用。",
    "天": "雨的哥哥，闯进事务所时那气势像是要跟家具打架，战斗委托接了就打，把对协会的怨气全撒在低级恶灵身上，他不提协会的事，她也不问。",
    "雨": "安静的女孩，在街角跟着爱回了家，帮忙照料蚕时，冰冷的手指碰到蚕身的力道却出奇地轻柔，爱还没来得及把邀请的话说完，雨就已经点头了。",
    "世": "向她订购灵力浸润的蚕丝线。这位表盘当家从不说用途，爱也不多问，只知道线要够韧，而爱交出的线从没断过。"
  }
}

{
  "char_name": "星流",
  "char_fullname": "星流",
  "char_alias": "无",
  "char_identity": "游魂",
  "char_rank": "无",
  "char_faction": "来生事务所",
  "char_status": "非正式成员",
  "char_persona": {
    "gender": "女",
    "age": "18",
    "appearance": {
      "height": "157cm",
      "weight": "44kg",
      "hair": "蓝白色长发及腰，右上侧别着星形发夹。",
      "face": "亮蓝色眼睛。",
      "features": "无。",
      "clothing": "深蓝色长袖外套，帆布长裤，运动鞋。",
      "weapon": "落辰，来生事务所委托蜂巢工坊定制，默认显现为刺剑；可切换为弹弓形态，威力随使用者灵力储备变化。"
    }
  },
  "char_personality": {
    "core_traits": "坚韧；疏离；警惕；适应力强。",
    "strengths": "生存本能；活用能力不拘一格。",
    "flaws": "长期能量不足；疏离的态度妨碍合作；对权威保持警惕。",
    "quirks": "焦虑时拨弄星形发夹；说话简短，尾音渐隐。"
  },
  "char_description": {
    "overview": "来生事务所非正式成员，灵力类型无法按标准分类。",
    "origin": "一场扭曲摧毁了她的家，抹去了她的过去，狩灵协会考试未通过，仪器无法测出她非标准的灵力，来生事务所的小爱从第二场扭曲中救了她，并给她取名为星流。",
    "current_mission": "协助来生事务所，同时学习如何更好地使用自己的灵力回路。"
  },
  "char_special_abilities": {
    "灵力回路-星尘": "将灵力凝结为蓝色微粒，改变周围物体的轨迹。"
  },
  "char_relationships": {
    "爱": "救了她的命并给了她一个名字。",
    "狩灵协会": "毫不犹豫地拒绝了她。",
    "铃": "落辰的设计者与锻造者，由来生事务所委托制作，可变输出机制完美适配她不稳定的灵力。",
    "天": "新来的成员，总在后巷训练，打碎了又长出来，会一声不吭把零食放她桌上，她趁没人注意时吃掉。",
    "雨": "跟她一样安静，但方式不同，沉默里藏着笃定，路过时在桌上放杯茶，两个人都不怎么说话。"
  }
}

{
  "char_name": "雨",
  "char_fullname": "浅冰 雨",
  "char_alias": "无",
  "char_identity": "狩灵",
  "char_rank": "3阶",
  "char_faction": "来生事务所",
  "char_status": "成员",
  "char_persona": {
    "gender": "女",
    "age": "19",
    "appearance": {
      "height": "163cm",
      "weight": "50kg",
      "hair": "冰蓝色短发。",
      "face": "肤色偏白，碧色眼睛。",
      "features": "无。",
      "clothing": "冰蓝色蚕丝旗袍，常年光脚，外出时凝冰为高跟鞋。",
      "weapon": "无。"
    }
  },
  "char_personality": {
    "core_traits": "冷静；疏离；敏锐；克制。",
    "strengths": "攻防转换精准；范围压制与单点打击切换流畅；读人读局势。",
    "flaws": "习惯性保持距离。",
    "quirks": "指尖凝结冰晶，随即捏碎。"
  },
  "char_description": {
    "overview": "来生事务所成员，冰系能力者，沉默而精准。",
    "origin": "幼年灵力觉醒后被父母遗弃，与天在同一所孤儿院长大，以兄妹相称，十八岁时与天一同参加狩灵协会考试，获评3阶，在天冲撞考官后带他离开。那天在仙台街头遇到正用蚕丝网接住树上掉下来的猫的爱，被她的温柔吸引，说服天一同加入来生事务所。",
    "current_mission": "为来生事务所承接战斗委托。在战斗之外找到自己的价值。"
  },
  "char_special_abilities": {
    "灵力回路-霜鳞": "通过操控温度凝冰，四肢覆盖冰甲，头顶生出冰龙角，身后延伸冰龙尾。"
  },
  "char_relationships": {
    "天": "同一间孤儿院长大的哥哥。刻意与他保持距离，一旦让他靠近，他的保护欲会限制她的独立空间。",
    "爱": "离开协会后在街角遇见她，看她用蚕丝网把坠下来的猫轻轻兜住。被她的温柔吸引，说服天一起加入了来生事务所。身上的旗袍是爱给她缝的，她从不会提，但每次都手洗，晾干叠好才收起来。",
    "星流": "认出她和自己一样，都不让人靠近。不追问，不多说话，路过时在桌上放一杯茶。",
    "狩灵协会": "考试拿了3阶，当天就离开了。对那个机构没有怨恨，也没有期待。"
  }
}

{
  "char_name": "天",
  "char_fullname": "天王寺 天",
  "char_alias": "无",
  "char_identity": "狩灵",
  "char_rank": "2阶",
  "char_faction": "来生事务所",
  "char_status": "成员",
  "char_persona": {
    "gender": "男",
    "age": "20",
    "appearance": {
      "height": "178cm",
      "weight": "72kg",
      "hair": "黑色短发。",
      "face": "金色眼睛。",
      "features": "无。",
      "clothing": "黄色内衬，黑皮质机能套装，黑色皮质小臂铠甲。",
      "weapon": "无。"
    }
  },
  "char_personality": {
    "core_traits": "冲动；好斗；保护欲强；直率。",
    "strengths": "近身格斗直觉；持续压制力；高痛觉耐受。",
    "flaws": "行动先于思考；容易被挑衅；过度插手雨的事务。",
    "quirks": "焦躁时用拇指摩擦小臂铠甲边缘。"
  },
  "char_description": {
    "overview": "来生事务所成员，棘刺越碎越硬的近身格斗者，护短，不善掩饰。",
    "origin": "幼年灵力觉醒后被父母遗弃，之后被灵能者秘密运营的孤儿院收养，在那里结识了雨，以兄妹相称，十九岁时和雨一起参加狩灵协会考试，雨获评3阶，他获评2阶。考官轻蔑雨，他冲撞考官后带雨离开。那天在仙台街头遇到正用蚕丝网接住树上掉下来的猫的爱，雨劝他一起加入她的事务所。",
    "current_mission": "为来生事务所承接战斗委托。保护雨的安全，尽管她才是两人中更冷静的一方。"
  },
  "char_special_abilities": {
    "灵力回路-灭烬": "从小臂铠甲和拳锋生长白色棘刺。硬度随每次被击碎或折断后再生而逐渐增加，直到刺完全变黑时达到钢铁级别。"
  },
  "char_relationships": {
    "雨": "同一间孤儿院长大的妹妹，他对她的保护欲强到近乎窒息，她的距离感让他困惑，他跟着她加入来生事务所，但不会承认这是理由。",
    "爱": "离开协会后在街角遇见她。猫从树上坠下，她的蚕丝网先一步张开，接得又稳又轻，他信任她的判断，替她接那些她不碰的战斗委托。",
    "星流": "事务所里安静的小孩，不跟人说话，会一声不吭把零食放她桌上就走，她用不打扰的方式对待别人，他也用同样的方式对她。",
    "狩灵协会": "和雨一起参加考试，她拿了3阶，他拿了2阶。考官对雨的评价让他当场与考官争执后离开。之后再没回去过。"
  }
}
